// « Lettre » of an application (F-UI-04, F-LET-01 to 07, ADR 0016): the versions (origin, status, active),
// the diff between two versions, the edition paragraph by paragraph (saved as a new version, never over
// an existing one), the choice of the active version and the final status (irreversible), the preview
// of a version with its ATS criteria and the warnings of the guardrails, and the export of the active
// version (PDF = the preview shown, T-ATS-13). Sender, place and date, subject and formulas are
// generated by the server: they are not edited here.
import { useCallback, useEffect, useMemo, useState } from 'react';
import { exportBlockers, wordDiff } from '@cv/core/export';
import { THEME_FONT_META } from '@cv/core/selection';
import {
  ApiError,
  api,
  decodeBase64,
  saveBlob,
  sha256Hex,
  type ApplicationDetail,
  type Lang,
  type LetterDraft,
  type LetterRenderResponse,
  type LettersResponse,
  type LetterVersion,
} from '../api';
import { buttonClass } from '../components/fields';
import { PdfPreview } from '../components/PdfPreview';
import { DiffText, when } from '../components/ProposalCard';
import { useCv } from '../state/cv-store';

const ROLES: Record<Lang, string[]> = {
  fr: ['vous', 'moi', 'nous'],
  en: ['opening', 'evidence', 'motivation', 'close'],
};
const ROLE_LABEL: Record<string, string> = {
  vous: 'vous (l’entreprise et son besoin)',
  moi: 'moi (réalisations de la bibliothèque)',
  nous: 'nous (apport et entretien)',
  opening: 'opening',
  evidence: 'evidence',
  motivation: 'motivation',
  close: 'close',
};
const MIME = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
} as const;
const input = 'w-full rounded border border-slate-300 px-2 py-1 text-sm';

type Recipient = NonNullable<LetterDraft['recipient']>;
const EMPTY_RECIPIENT: Recipient = { civility: null, name: null, function: null, company: null, city: null };

function emptyDraft(lang: Lang): LetterDraft {
  return {
    recipient: null,
    paragraphs: (lang === 'fr' ? ['vous', 'moi', 'nous'] : ['opening', 'evidence', 'motivation', 'close']).map(
      (role) => ({
        role,
        text: '',
      }),
    ),
    sourceIds: [],
    basedOn: null,
  };
}

const draftOf = (v: LetterVersion): LetterDraft => ({
  recipient: v.recipient,
  paragraphs: v.paragraphs.map((p) => ({ role: p.role, text: p.text })),
  sourceIds: [...v.sourceIds],
  basedOn: v.version,
});

/** Readable label of a cited element (« Ingénieure logiciel embarqué – MedTech Exemple SAS »). */
function useSourceLabel(): (id: string) => string {
  const library = useCv((s) => s.library?.library ?? null);
  return useCallback(
    (id: string) => {
      if (!library) return id;
      for (const items of Object.values(library) as Array<Array<Record<string, unknown>>>) {
        for (const item of items) {
          const text = (b: unknown) => (b && typeof b === 'object' ? ((b as { fr?: string }).fr ?? '') : '');
          if (item.id === id) {
            return [
              text(item.position) || text(item.degree) || text(item.name) || (item.short as string) || id,
              item.organization ?? item.institution,
            ]
              .filter(Boolean)
              .join(' – ');
          }
          for (const b of (item.bullets as
            Array<{ id: string; variants: Array<{ text: { fr: string | null } }> }> | undefined) ?? []) {
            if (b.id === id) return `puce « ${(b.variants[0]?.text.fr ?? id).slice(0, 60)}… »`;
          }
        }
      }
      return `${id} (introuvable)`;
    },
    [library],
  );
}

function VersionDiff({ a, b }: { a: LetterVersion; b: LetterVersion }) {
  const rec = (v: LetterVersion) =>
    v.recipient
      ? [v.recipient.civility, v.recipient.name, v.recipient.function, v.recipient.company, v.recipient.city]
          .filter(Boolean)
          .join(', ')
      : '';
  const n = Math.max(a.paragraphs.length, b.paragraphs.length);
  return (
    <div
      className="space-y-2 rounded border border-slate-200 bg-slate-50 p-3 text-sm"
      aria-label="Différences entre versions"
    >
      <p className="font-medium">
        Différences de la v{a.version} à la v{b.version}
      </p>
      {rec(a) !== rec(b) && (
        <div>
          <div className="text-xs text-slate-500">Destinataire</div>
          <DiffText segments={wordDiff(rec(a), rec(b))} />
        </div>
      )}
      {Array.from({ length: n }, (_, i) => {
        const pa = a.paragraphs[i];
        const pb = b.paragraphs[i];
        return (
          <div key={i}>
            <div className="text-xs text-slate-500">
              § {i + 1} ({pa?.role ?? '—'} → {pb?.role ?? '—'})
            </div>
            <DiffText segments={wordDiff(pa?.text ?? null, pb?.text ?? null)} />
          </div>
        );
      })}
    </div>
  );
}

export function LetterPage({
  applicationId,
  initialLang,
  version: refreshVersion,
  onChanged,
  navigate,
}: {
  applicationId: string;
  initialLang: Lang | null;
  version: number;
  onChanged: () => void;
  navigate: (path: string) => void;
}) {
  const [app, setApp] = useState<ApplicationDetail | null>(null);
  const [lang, setLang] = useState<Lang | null>(initialLang);
  const [data, setData] = useState<LettersResponse | null>(null);
  const [selected, setSelected] = useState<number | null>(null);
  const [compare, setCompare] = useState<number[]>([]);
  const [draft, setDraft] = useState<LetterDraft | null>(null);
  const [dirty, setDirty] = useState(false);
  const [notice, setNotice] = useState<{ tone: 'ok' | 'error'; text: string } | null>(null);
  const [preview, setPreview] = useState<{
    response: LetterRenderResponse;
    bytes: Uint8Array<ArrayBuffer>;
    sha: string;
  } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const sourceLabel = useSourceLabel();

  const load = useCallback(async () => {
    const [detail, letters] = await Promise.all([api.application(applicationId), api.letters(applicationId)]);
    setApp(detail);
    setData(letters);
    return { detail, letters };
  }, [applicationId]);

  useEffect(() => {
    load().catch((e: Error) => setNotice({ tone: 'error', text: e.message }));
  }, [load, refreshVersion]);

  const currentLang: Lang = lang ?? app?.application.lang ?? 'fr';
  const versions = useMemo(() => data?.letters[currentLang] ?? [], [data, currentLang]);
  const active = data?.active[currentLang] ?? null;
  const shown = versions.find((v) => v.version === selected) ?? null;

  // Default selection: the active version, otherwise the last one; a new draft when there is none.
  useEffect(() => {
    if (!data || dirty) return;
    const pick =
      selected !== null && versions.some((v) => v.version === selected)
        ? selected
        : (active ?? versions.at(-1)?.version ?? null);
    setSelected(pick);
    const v = versions.find((x) => x.version === pick);
    setDraft(v ? draftOf(v) : emptyDraft(currentLang));
  }, [data, currentLang, versions, active]);

  // Preview of the version shown (the day of the request).
  useEffect(() => {
    if (selected === null) {
      setPreview(null);
      return;
    }
    let cancelled = false;
    api
      .renderLetter(applicationId, currentLang, selected)
      .then(async (response) => {
        const bytes = decodeBase64(response.pdfBase64);
        if (!cancelled) setPreview({ response, bytes, sha: await sha256Hex(bytes) });
      })
      .catch((e: Error) => !cancelled && setNotice({ tone: 'error', text: e.message }));
    return () => {
      cancelled = true;
    };
  }, [applicationId, currentLang, selected, data]);

  const run = async (label: string, fn: () => Promise<void>) => {
    setBusy(label);
    setNotice(null);
    try {
      await fn();
    } catch (e) {
      setNotice({
        tone: 'error',
        text: e instanceof ApiError && e.hint ? `${e.message} (${e.hint})` : (e as Error).message,
      });
    } finally {
      setBusy(null);
    }
  };

  const save = () =>
    run('save', async () => {
      if (!draft) return;
      const r = await api.saveLetter(applicationId, currentLang, draft);
      setDirty(false);
      setSelected(r.version.version);
      await load();
      onChanged();
      setNotice({ tone: 'ok', text: `Version ${r.version.version} enregistrée (rien n'est écrasé).` });
    });

  const activate = (v: number | null) =>
    run('active', async () => {
      await api.setActiveLetter(applicationId, currentLang, v);
      await load();
      onChanged();
    });

  const finalize = (v: number) =>
    run('final', async () => {
      if (
        !window.confirm(
          `Marquer la version ${v} comme finale ? Elle ne pourra plus être modifiée ni revenir en brouillon.`,
        )
      )
        return;
      await api.finalizeLetter(applicationId, currentLang, v);
      await load();
      onChanged();
    });

  const exportLetter = (format: 'pdf' | 'docx') =>
    run(format, async () => {
      if (!preview || !preview.response.active) return;
      const r = await api.exportLetter(applicationId, currentLang, format, preview.sha);
      const bytes = format === 'pdf' ? preview.bytes : decodeBase64(r.fileBase64 ?? '');
      const blob = new Blob([bytes], { type: MIME[format] });
      if (format === 'pdf') {
        const blobSha = await sha256Hex(await blob.arrayBuffer());
        if (blobSha !== preview.sha || r.sha256 !== preview.sha) {
          throw new Error("Export PDF refusé : le fichier diffère de l'aperçu affiché (T-ATS-13)");
        }
      }
      saveBlob(blob, r.fileName);
      setNotice({
        tone: 'ok',
        text: `${format.toUpperCase()} exporté : ${r.fileName} ; copie rangée dans la candidature (${r.savedTo}).`,
      });
      onChanged();
    });

  const setRecipient = (patch: Partial<Recipient>) => {
    if (!draft) return;
    const next = { ...(draft.recipient ?? EMPTY_RECIPIENT), ...patch };
    const empty = Object.values(next).every((x) => x === null || x === '');
    setDraft({ ...draft, recipient: empty ? null : next });
    setDirty(true);
  };
  const setParagraph = (i: number, patch: Partial<{ role: string; text: string }>) => {
    if (!draft) return;
    setDraft({ ...draft, paragraphs: draft.paragraphs.map((p, j) => (j === i ? { ...p, ...patch } : p)) });
    setDirty(true);
  };

  if (!app || !data || !draft) {
    return <main className="p-4 text-sm text-slate-600">{notice?.text ?? 'Chargement de la lettre…'}</main>;
  }
  const blockers = preview ? exportBlockers(preview.response.report, 'compacte') : [];
  const compared = compare.map((n) => versions.find((v) => v.version === n)).filter((v): v is LetterVersion => !!v);
  const r = draft.recipient ?? EMPTY_RECIPIENT;

  return (
    <main className="flex-1 space-y-3 p-4">
      <div className="flex flex-wrap items-center gap-3">
        <button type="button" className={buttonClass.small} onClick={() => navigate('/candidatures')}>
          ← Candidatures
        </button>
        <h2 className="text-lg font-semibold">
          Lettre de motivation : {app.application.company} – {app.application.jobTitle}
        </h2>
        <span className="flex gap-1" role="group" aria-label="Langue de la lettre">
          {(['fr', 'en'] as const).map((l) => (
            <button
              key={l}
              type="button"
              aria-pressed={currentLang === l}
              className={currentLang === l ? buttonClass.primary : buttonClass.secondary}
              onClick={() => {
                setLang(l);
                setSelected(null);
                setCompare([]);
                setDirty(false);
              }}
            >
              {l === 'fr' ? 'FR' : `EN (${app.application.enVariant})`}
            </button>
          ))}
        </span>
      </div>
      <p className="text-xs text-slate-600">
        Le serveur génère l'expéditeur, le lieu et la date (du jour), l'objet, les formules d'appel et de politesse et «
        P. J. : CV ». Chaque enregistrement crée une nouvelle version ; seule la version active s'exporte.
      </p>
      {notice && (
        <p role="status" className={`text-sm ${notice.tone === 'ok' ? 'text-green-800' : 'text-red-800'}`}>
          {notice.text}
        </p>
      )}

      <div className="grid gap-4 xl:grid-cols-[15rem_minmax(0,1fr)_minmax(0,1fr)]">
        <section aria-labelledby="versions-title" className="space-y-2">
          <h3 id="versions-title" className="font-semibold">
            Versions ({versions.length})
          </h3>
          {versions.length === 0 && (
            <p className="text-sm text-slate-600">
              Aucune version : rédigez-la ici, ou demandez à Claude (prompt rediger-lettre).
            </p>
          )}
          <ul className="space-y-1">
            {[...versions].reverse().map((v) => (
              <li
                key={v.version}
                className={`rounded border p-2 text-sm ${v.version === selected ? 'border-[#1F4E79] bg-white' : 'border-slate-200 bg-white/60'}`}
              >
                <button
                  type="button"
                  className="w-full text-left"
                  onClick={() => {
                    setSelected(v.version);
                    setDraft(draftOf(v));
                    setDirty(false);
                  }}
                >
                  <span className="font-medium">v{v.version}</span> · {v.origin === 'claude' ? 'Claude' : 'vous'}
                  {v.basedOn ? ` (de v${v.basedOn})` : ''}
                  <span className="block text-xs text-slate-500">{when(v.createdAt)}</span>
                </button>
                <span className="flex flex-wrap items-center gap-1 text-xs">
                  {v.version === active && <span className="rounded bg-green-100 px-1 text-green-900">active</span>}
                  {v.status === 'finale' && <span className="rounded bg-slate-200 px-1">finale</span>}
                  {v.checks.length > 0 && (
                    <span className="rounded bg-amber-100 px-1 text-amber-900">⚠ {v.checks.length}</span>
                  )}
                  <label className="ml-auto flex items-center gap-1">
                    <input
                      type="checkbox"
                      checked={compare.includes(v.version)}
                      onChange={(e) =>
                        setCompare((c) =>
                          e.target.checked
                            ? [...c, v.version].slice(-2).sort((x, y) => x - y)
                            : c.filter((x) => x !== v.version),
                        )
                      }
                    />
                    comparer
                  </label>
                </span>
              </li>
            ))}
          </ul>
          {shown && (
            <div className="flex flex-wrap gap-1">
              {shown.version !== active ? (
                <button
                  type="button"
                  className={buttonClass.small}
                  disabled={busy !== null}
                  onClick={() => void activate(shown.version)}
                >
                  Rendre active
                </button>
              ) : (
                <button
                  type="button"
                  className={buttonClass.small}
                  disabled={busy !== null}
                  onClick={() => void activate(null)}
                >
                  Retirer l'activation
                </button>
              )}
              {shown.status === 'brouillon' && (
                <button
                  type="button"
                  className={buttonClass.small}
                  disabled={busy !== null}
                  onClick={() => void finalize(shown.version)}
                >
                  Marquer comme finale
                </button>
              )}
            </div>
          )}
        </section>

        <section aria-labelledby="edit-title" className="space-y-3">
          <h3 id="edit-title" className="font-semibold">
            {shown ? `Version ${shown.version}` : 'Nouvelle lettre'}
            {dirty && <span className="ml-2 text-xs font-normal text-amber-800">modifiée, non enregistrée</span>}
          </h3>
          {shown?.status === 'finale' && (
            <p className="text-xs text-slate-600">
              Version finale : elle ne change plus. Vos modifications créeront une nouvelle version.
            </p>
          )}
          {compared.length === 2 && <VersionDiff a={compared[0]!} b={compared[1]!} />}
          <fieldset className="grid gap-2 rounded border border-slate-200 bg-white p-2 sm:grid-cols-2">
            <legend className="px-1 text-sm">Destinataire</legend>
            <label className="text-sm">
              Civilité
              <select
                className={input}
                value={r.civility ?? ''}
                onChange={(e) => setRecipient({ civility: (e.target.value || null) as Recipient['civility'] })}
              >
                <option value="">inconnue</option>
                <option value="madame">Madame</option>
                <option value="monsieur">Monsieur</option>
              </select>
            </label>
            {(['name', 'function', 'company', 'city'] as const).map((k) => (
              <label key={k} className="text-sm">
                {{ name: 'Nom', function: 'Fonction', company: 'Entreprise', city: 'Ville' }[k]}
                <input
                  className={input}
                  value={r[k] ?? ''}
                  placeholder={k === 'company' ? app.application.company : ''}
                  onChange={(e) => setRecipient({ [k]: e.target.value === '' ? null : e.target.value })}
                />
              </label>
            ))}
          </fieldset>
          {draft.paragraphs.map((p, i) => (
            <div key={i} className="space-y-1 rounded border border-slate-200 bg-white p-2">
              <div className="flex items-center gap-2 text-sm">
                § {i + 1}
                <select
                  aria-label={`Rôle du paragraphe ${i + 1}`}
                  className="rounded border border-slate-300 px-1"
                  value={p.role}
                  onChange={(e) => setParagraph(i, { role: e.target.value })}
                >
                  {ROLES[currentLang].map((role) => (
                    <option key={role} value={role}>
                      {ROLE_LABEL[role]}
                    </option>
                  ))}
                </select>
                {draft.paragraphs.length > 3 && (
                  <button
                    type="button"
                    className={`${buttonClass.small} ml-auto`}
                    onClick={() => {
                      setDraft({ ...draft, paragraphs: draft.paragraphs.filter((_, j) => j !== i) });
                      setDirty(true);
                    }}
                  >
                    Retirer
                  </button>
                )}
              </div>
              <textarea
                aria-label={`Texte du paragraphe ${i + 1}`}
                className={`${input} min-h-24`}
                value={p.text}
                onChange={(e) => setParagraph(i, { text: e.target.value })}
              />
              {shown?.checks
                .filter((c) => c.paragraph === i)
                .map((c, j) => (
                  <p key={j} className="text-xs text-amber-900">
                    ⚠ {c.rule} : {c.message}
                  </p>
                ))}
            </div>
          ))}
          {draft.paragraphs.length < 4 && (
            <button
              type="button"
              className={buttonClass.small}
              onClick={() => {
                const role = currentLang === 'fr' ? 'moi' : 'evidence';
                const at = draft.paragraphs.length - 1;
                const paragraphs = [...draft.paragraphs];
                paragraphs.splice(at, 0, { role, text: '' });
                setDraft({ ...draft, paragraphs });
                setDirty(true);
              }}
            >
              + Paragraphe
            </button>
          )}
          {shown?.checks
            .filter((c) => c.paragraph === null)
            .map((c, j) => (
              <p key={j} className="text-xs text-amber-900">
                ⚠ {c.rule} : {c.message}
              </p>
            ))}
          {draft.sourceIds.length > 0 && (
            <div className="text-xs text-slate-600">
              Éléments cités (sourceIds) :
              <ul className="list-disc pl-5">
                {draft.sourceIds.map((id) => (
                  <li key={id}>{sourceLabel(id)}</li>
                ))}
              </ul>
            </div>
          )}
          <div className="flex gap-2">
            <button
              type="button"
              className={buttonClass.primary}
              disabled={!dirty || busy !== null}
              onClick={() => void save()}
            >
              Enregistrer comme nouvelle version
            </button>
            <button
              type="button"
              className={buttonClass.secondary}
              disabled={!dirty || busy !== null}
              onClick={() => {
                setDraft(shown ? draftOf(shown) : emptyDraft(currentLang));
                setDirty(false);
              }}
            >
              Annuler les modifications
            </button>
          </div>
        </section>

        <section aria-labelledby="preview-title" className="space-y-2">
          <h3 id="preview-title" className="font-semibold">
            Aperçu {shown ? `de la v${shown.version}` : ''}
          </h3>
          <p className="flex items-center gap-1 text-xs text-slate-600">
            {/* F-MOD-05: the single letter template takes the font and the accent of the application's theme. */}
            <span
              aria-hidden="true"
              className="inline-block h-3 w-3 rounded-sm"
              style={{ backgroundColor: app.selection.template.theme.accent }}
            />
            Thème de la candidature : {THEME_FONT_META[app.selection.template.theme.font].label}, accent{' '}
            {app.selection.template.theme.accent} (modifiable dans les réglages de la candidature)
          </p>
          {preview && (
            <>
              <p className="text-xs text-slate-600">
                {preview.response.pages} page(s), remplissage {Math.round(preview.response.fillRatio * 100)} % ·{' '}
                {preview.response.fileName}
              </p>
              <div className="flex flex-wrap gap-2">
                {(['pdf', 'docx'] as const).map((format) => (
                  <button
                    key={format}
                    type="button"
                    className={buttonClass.primary}
                    disabled={!preview.response.active || blockers.length > 0 || busy !== null || dirty}
                    onClick={() => void exportLetter(format)}
                  >
                    {busy === format ? 'Export…' : `Exporter ${format.toUpperCase()}`}
                  </button>
                ))}
                <span className="text-xs text-amber-800">1 page non garantie en DOCX</span>
              </div>
              {!preview.response.active && (
                <p className="text-xs text-slate-600">
                  Seule la version active s'exporte : rendez cette version active.
                </p>
              )}
              {blockers.length > 0 && (
                <div role="status" className="rounded bg-red-50 px-3 py-1.5 text-sm text-red-900">
                  <span className="font-semibold">Export bloqué</span>
                  <ul className="list-disc pl-5">
                    {blockers.map((b) => (
                      <li key={`${b.code}|${b.message}`}>{b.message}</li>
                    ))}
                  </ul>
                </div>
              )}
              <ul className="flex flex-wrap gap-1 text-xs" aria-label="Critères de lisibilité de la lettre">
                {preview.response.report.criteria.map((c) => (
                  <li
                    key={c.id}
                    title={c.message}
                    className={`rounded px-1.5 py-0.5 ${c.status === 'green' ? 'bg-green-50 text-green-900' : c.status === 'orange' ? 'bg-amber-50 text-amber-900' : c.status === 'red' ? 'bg-red-50 text-red-900' : 'bg-slate-100 text-slate-600'}`}
                  >
                    {c.id}
                  </li>
                ))}
              </ul>
              <PdfPreview data={preview.bytes} />
            </>
          )}
        </section>
      </div>
    </main>
  );
}
